package com.bank.spark.service;

import java.util.BitSet;

// A compact bloom filter: never false negatives, sometimes false positives.
public class SimpleBloomFilter {
    private final BitSet bits;
    private final int size;
    private final int hashCount;

    public SimpleBloomFilter(int size, int hashCount) {
        this.size = size;
        this.hashCount = hashCount;
        this.bits = new BitSet(size);
    }

    public void add(String value) {
        for (int i = 0; i < hashCount; i++) {
            bits.set(indexFor(value, i));
        }
    }

    // "mightContain": all bits set → probably present; any bit clear → definitely absent.
    public boolean mightContain(String value) {
        for (int i = 0; i < hashCount; i++) {
            if (!bits.get(indexFor(value, i))) {
                return false; // definitely not present — safe to skip
            }
        }
        return true; // probably present — must read
    }

    private int indexFor(String value, int seed) {
        int h = (value.hashCode() * 31 + seed * 0x9E3779B1);
        return Math.floorMod(h, size);
    }
}
