package com.bank.spark.model;

import com.bank.spark.service.SimpleBloomFilter;

import java.util.List;

// A block of high-cardinality unsorted ids with wide min/max and a bloom filter.
public class IdBlock {
    private final int id;
    private final String minId;   // wide range because unsorted
    private final String maxId;
    private final SimpleBloomFilter bloom;

    public IdBlock(int id, List<String> txnIds) {
        this.id = id;
        this.minId = txnIds.stream().min(String::compareTo).orElse("");
        this.maxId = txnIds.stream().max(String::compareTo).orElse("");
        this.bloom = new SimpleBloomFilter(256, 3);
        txnIds.forEach(bloom::add);
    }

    public int getId() { return id; }
    public String getMinId() { return minId; }
    public String getMaxId() { return maxId; }
    public SimpleBloomFilter getBloom() { return bloom; }
}
