package com.bank.spark;

import com.bank.spark.model.IdBlock;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BloomLookupDemo {

    private static final Logger log = Logger.getLogger(BloomLookupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Unsorted blocks: ids are scattered, so min/max ranges overlap heavily.
        List<IdBlock> blocks = List.of(
                new IdBlock(0, List.of("TX-000001", "TX-500000", "TX-999998")),
                new IdBlock(1, List.of("TX-000002", "TX-250000", "TX-888000")),
                new IdBlock(2, List.of("TX-000003", "TX-424242", "TX-777777")),
                new IdBlock(3, List.of("TX-000004", "TX-600000", "TX-999999"))
        );

        String lookup = "TX-424242"; // lives only in block 2

        // 1) min/max cannot skip: every block's [min..max] covers the lookup.
        log.warning("min/max check for " + lookup + " (unsorted ids):");
        for (IdBlock b : blocks) {
            boolean inRange = lookup.compareTo(b.getMinId()) >= 0 && lookup.compareTo(b.getMaxId()) <= 0;
            log.warning("  block " + b.getId() + " [" + b.getMinId() + ".." + b.getMaxId() + "] -> "
                    + (inRange ? "cannot skip (in range)" : "skip"));
        }

        // 2) dictionary absent for high cardinality — no membership page to check.
        log.warning("Dictionary filtering: column dropped dictionary encoding (too many distinct ids) -> no help");

        // 3) bloom filter skips blocks that definitely do not contain the id.
        log.info("Bloom filter check for " + lookup + ":");
        int read = 0;
        for (IdBlock b : blocks) {
            boolean maybe = b.getBloom().mightContain(lookup);
            if (maybe) read++;
            log.info("  block " + b.getId() + " -> " + (maybe ? "READ (probably present)" : "SKIP (definitely not present)"));
        }
        int finalRead = read;
        log.info(() -> "Bloom filter: read only " + finalRead + " of " + blocks.size() + " blocks for the point lookup");
    }
}

